def get_cookie_max_age(
    self, app: "Flask"
) -> t.Optional[int]:
    """Returns the max age for the session cookie.  This currently
    just returns the value of the ``SESSION_COOKIE_MAX_AGE`` setting.
    If the value is ``None``, no ``Max-Age`` attribute is set for the
    cookie.

    The value can be an ``int`` (seconds) or a ``datetime.timedelta``.
    Negative values raise ``ValueError``. Other types raise ``TypeError``.
    """
    from datetime import timedelta

    val = app.config["SESSION_COOKIE_MAX_AGE"]

    if val is None:
        return None

    if isinstance(val, timedelta):
        result = int(val.total_seconds())
        if result < 0:
            raise ValueError(
                "SESSION_COOKIE_MAX_AGE must not be negative."
            )
        return result

    if isinstance(val, int):
        if val < 0:
            raise ValueError(
                "SESSION_COOKIE_MAX_AGE must not be negative."
            )
        return val

    raise TypeError(
        "SESSION_COOKIE_MAX_AGE must be None, int, or timedelta."
    )
